SELECT DATE_TRUNC('YEAR', signup_date) AS year_start, CORR(credit_limit, age) AS corr_credit_limit_age, SUM(credit_limit) FILTER (WHERE country = 'US') AS us_total_credit_limit, COUNT_IF(country = 'SG') AS sg_events, CORR(age, credit_limit) AS corr_age_credit_limit, ROUND(SUM(age) / NULLIF(COUNT(CASE WHEN segment = 'SMB' THEN 1 END), 0), 2) AS age_per_smb FROM customers GROUP BY DATE_TRUNC('YEAR', signup_date) ORDER BY corr_age_credit_limit;
